const DIAS_SEMANA = ['D', 'S', 'T', 'Q', 'Q', 'S', 'S'];

type TipoDisponibilidade = 'disponivel' | 'indisponivel';

type RegistroPresenca = {
  datas: string[];
  datasIndisponiveis: string[];
};

function normalizarRegistroPresenca(registro: any, hoje: string): RegistroPresenca {
  const datas = Array.isArray(registro?.datas)
    ? registro.datas.filter((data: unknown): data is string => typeof data === 'string').slice(0, 5)
    : typeof registro?.data === 'string'
      ? [registro.data]
      : [hoje];

  const datasIndisponiveis = Array.isArray(registro?.datasIndisponiveis)
    ? registro.datasIndisponiveis
      .filter((data: unknown): data is string => typeof data === 'string')
      .slice(0, 5)
    : [];

  return {
    datas: datas.filter((data: string) => !datasIndisponiveis.includes(data)),
    datasIndisponiveis,
  };
}

function montarDiasCalendario(mesVisivel: Date) {
  const ano = mesVisivel.getFullYear();
  const mes = mesVisivel.getMonth();
  const primeiroDia = new Date(ano, mes, 1).getDay();
  const totalDias = new Date(ano, mes + 1, 0).getDate();
  const dias: Array<Date | null> = Array(primeiroDia).fill(null);

  for (let dia = 1; dia <= totalDias; dia += 1) {
    dias.push(new Date(ano, mes, dia));
  }

  while (dias.length % 7 !== 0) dias.push(null);
  return dias;
}

function BadgePendenteAnimado({
  children,
}: {
  children: ReactNode;
}) {
  const pulso = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    const animacaoPulso = Animated.loop(
      Animated.sequence([
        Animated.timing(pulso, {
          toValue: 1,
          duration: 700,
          easing: Easing.inOut(Easing.ease),
          useNativeDriver: true,
        }),
        Animated.timing(pulso, {
          toValue: 0,
          duration: 700,
          easing: Easing.inOut(Easing.ease),
          useNativeDriver: true,
        }),
      ])
    );

    animacaoPulso.start();
    return () => animacaoPulso.stop();
  }, [pulso]);

  return (
    <Animated.View
      style={{
        opacity: pulso.interpolate({ inputRange: [0, 1], outputRange: [0.55, 1] }),
        transform: [
          {
            scale: pulso.interpolate({ inputRange: [0, 1], outputRange: [1, 1.08] }),
          },
        ],
      }}
    >
      {children}
    </Animated.View>
  );
}

function CardPresencaAnimado({
  index,
  children,
}: {
  index: number;
  children: ReactNode;
}) {
  const entrada = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    const animacao = Animated.spring(entrada, {
      toValue: 1,
      delay: Math.min(index * 55, 550),
      friction: 8,
      tension: 68,
      useNativeDriver: true,
    });

    animacao.start();
    return () => animacao.stop();
  }, [entrada, index]);

  return (
    <Animated.View
      style={[
        styles.userCardWrapper,
        {
          opacity: entrada,
          transform: [
            {
              translateY: entrada.interpolate({
                inputRange: [0, 1],
                outputRange: [28, 0],
              }),
            },
            {
              scale: entrada.interpolate({
                inputRange: [0, 1],
                outputRange: [0.97, 1],
              }),
            },
          ],
        },
      ]}
    >
      {children}
    </Animated.View>
  );
}

