import { initializeApp } from 'firebase/app';
import { getAuth } from 'firebase/auth';
import { getFirestore } from 'firebase/firestore';
import { getStorage } from 'firebase/storage';
import { getDatabase } from 'firebase/database';
import {
  getMessaging,
  isSupported,
} from 'firebase/messaging';
import type { Messaging } from 'firebase/messaging';

const firebaseConfig = {
  apiKey: 'AIzaSyDdF-FLm64uCpdZ0UFHrV50cdgkO9RTi1E',
  authDomain: 'worship-8e304.firebaseapp.com',
  projectId: 'worship-8e304',
  storageBucket: 'worship-8e304.appspot.com',
  messagingSenderId: '219441831339',
  appId: '1:219441831339:web:e36d2d036a426e48c286ee',
  measurementId: 'G-D8WPC573FR',
  databaseURL:
    'https://worship-8e304-default-rtdb.firebaseio.com',
};

const app = initializeApp(firebaseConfig);

const auth = getAuth(app);
const firestore = getFirestore(app);
const storage = getStorage(app);
const database = getDatabase(app);

/*
 * Firebase Cloud Messaging funciona somente no ambiente Web
 * com suporte a Service Worker, Push API e notificações.
 *
 * Nos ambientes Android/iOS nativos, retorna null para não
 * interferir nas notificações gerenciadas pelo Expo.
 */
const messagingPromise: Promise<Messaging | null> =
  typeof window !== 'undefined' &&
  typeof navigator !== 'undefined' &&
  'serviceWorker' in navigator
    ? isSupported()
        .then(suportado => {
          if (!suportado) {
            console.log(
              'Firebase Messaging não é suportado neste navegador.'
            );

            return null;
          }

          return getMessaging(app);
        })
        .catch(error => {
          console.log(
            'Não foi possível inicializar o Firebase Messaging:',
            error
          );

          return null;
        })
    : Promise.resolve(null);

export {
  app,
  auth,
  firestore,
  storage,
  database,
  messagingPromise,
};