import React, { useEffect, useRef, useState } from 'react';
import { View, ActivityIndicator, StyleSheet, Platform, SafeAreaView, Text, Pressable } from 'react-native';
import { createNavigationContainerRef, NavigationContainer } from '@react-navigation/native';
import { onAuthStateChanged, User } from 'firebase/auth';
import { collection, doc, onSnapshot, query, setDoc } from 'firebase/firestore';

import AuthNavigator from './src/navigation/AuthNavigator';
import AppNavigator from './src/navigation/AppNavigator';
import { auth, firestore } from './src/services/firebaseConfig';
import { setInstalledAppBadge } from './src/services/appBadge';
import { registerFirebaseWebPush } from './src/services/pushNotifications';
import Toast from 'react-native-toast-message';
import InstallPWAButton from './src/components/InstallPWAButton';

import * as Notifications from 'expo-notifications';
import Constants from 'expo-constants';

const navigationRef = createNavigationContainerRef<any>();

// Configuração global para notificações (evita conflitos)
Notifications.setNotificationHandler({
  handleNotification: async () => ({
    shouldShowAlert: true,
    shouldPlaySound: true,
    shouldSetBadge: true,
  }),
});

function useRegisterForPushNotifications(usuario: User | null) {
  useEffect(() => {
    async function register() {
      if (!usuario) return;

      if (Platform.OS === 'web') {
        if (typeof window !== 'undefined' && 'Notification' in window && Notification.permission !== 'granted') {
          return;
        }

        await registerFirebaseWebPush(usuario);
        return;
      }

      if (Constants.isDevice) {
        const { status: existingStatus } = await Notifications.getPermissionsAsync();
        let finalStatus = existingStatus;

        if (existingStatus === 'undetermined') {
          const { status } = await Notifications.requestPermissionsAsync();
          finalStatus = status;
        }

        if (finalStatus !== 'granted') {
          return;
        }

        const token = (await Notifications.getExpoPushTokenAsync()).data;

        await setDoc(
          doc(firestore, 'usuarios', usuario.uid),
          { expoPushToken: token },
          { merge: true }
        );

        console.log('Token salvo:', token);
      }
    }

    register();
  }, [usuario]);
}

function useWebNotificationGate(usuario: User | null) {
  const [permission, setPermission] = useState<
    NotificationPermission | 'unsupported' | 'checking'
  >('checking');

  const [registering, setRegistering] = useState(false);
  const [continuarSemNotificacoes, setContinuarSemNotificacoes] = useState(false);

  useEffect(() => {
    if (Platform.OS !== 'web' || !usuario || typeof window === 'undefined') {
      setPermission('checking');
      setContinuarSemNotificacoes(false);
      return;
    }

    if (!('Notification' in window) || !('serviceWorker' in navigator)) {
      setPermission('unsupported');
      return;
    }

    setPermission(Notification.permission);

    const handleFocus = () => setPermission(Notification.permission);

    window.addEventListener('focus', handleFocus);

    return () => window.removeEventListener('focus', handleFocus);
  }, [usuario]);

  const requestPermission = async () => {
    if (
      !usuario ||
      Platform.OS !== 'web' ||
      typeof window === 'undefined' ||
      !('Notification' in window)
    ) {
      setContinuarSemNotificacoes(true);
      return;
    }

    const permissaoAtual = Notification.permission;

    // O navegador não permite solicitar novamente uma permissão bloqueada.
    // Nesse caso, orienta o usuário a liberá-la nas configurações do site.
    if (permissaoAtual === 'denied') {
      setPermission('denied');

      window.alert(
        'As notificações estão bloqueadas.\n\n' +
        'Para ativar:\n' +
        '1. Toque no ícone ao lado do endereço do site.\n' +
        '2. Abra "Permissões".\n' +
        '3. Selecione "Notificações".\n' +
        '4. Escolha "Permitir".\n' +
        '5. Atualize a página.'
      );

      setContinuarSemNotificacoes(true);
      return;
    }

    // Se a permissão já foi concedida, apenas atualiza o registro no Firebase.
    if (permissaoAtual === 'granted') {
      setPermission('granted');
      setContinuarSemNotificacoes(true);

      registerFirebaseWebPush(usuario).catch((error) => {
        console.log('Erro ao registrar notificações em segundo plano:', error);
      });

      return;
    }

    setRegistering(true);

    try {
      // Esta chamada ocorre diretamente após o toque do usuário para que o
      // navegador possa exibir a solicitação nativa de permissão.
      const resultado = await Notification.requestPermission();
      setPermission(resultado);

      if (resultado === 'granted') {
        // Libera a entrada no app sem aguardar o registro do token no Firebase.
        setContinuarSemNotificacoes(true);

        registerFirebaseWebPush(usuario).catch((error) => {
          console.log('Erro ao registrar notificações em segundo plano:', error);
        });

        return;
      }

      if (resultado === 'denied') {
        window.alert(
          'A permissão foi bloqueada.\n\n' +
          'Para ativar posteriormente, toque no ícone ao lado do endereço ' +
          'do site, abra "Permissões" e permita as notificações.'
        );
      } else {
        window.alert(
          'A solicitação não foi concluída.\n\n' +
          'Você poderá ativar as notificações depois nas permissões do site.'
        );
      }

      // Recusar ou fechar a solicitação não pode impedir a abertura do app.
      setContinuarSemNotificacoes(true);
    } catch (error) {
      console.log('Erro ao solicitar permissão de notificação:', error);

      window.alert(
        'Não foi possível abrir a solicitação de notificações.\n\n' +
        'Toque no ícone ao lado do endereço do site, abra "Permissões" ' +
        'e permita as notificações.'
      );

      setContinuarSemNotificacoes(true);
    } finally {
      setRegistering(false);
    }
  };

  return {
    shouldBlock:
      Platform.OS === 'web' &&
      !!usuario &&
      permission === 'default' &&
      !continuarSemNotificacoes,
    permission,
    registering,
    requestPermission,
    continueWithoutNotifications: () => setContinuarSemNotificacoes(true),
  };
}

function useInstalledAppBadge(usuario: User | null) {
  useEffect(() => {
    if (Platform.OS !== 'web' || !usuario) {
      setInstalledAppBadge(0);
      return;
    }

    let escalaCount = 0;
    let repertorioCount = 0;
    let avisoCount = 0;

    const updateBadge = () => {
      setInstalledAppBadge(escalaCount + repertorioCount + avisoCount);
    };

    const unsubscribeEscalas = onSnapshot(
      doc(firestore, 'meta', 'escalas'),
      (snapshot) => {
        escalaCount = Number(snapshot.data()?.newCount || 0);
        updateBadge();
      }
    );

    const unsubscribeRepertorios = onSnapshot(
      doc(firestore, 'meta', 'repertorios'),
      (snapshot) => {
        repertorioCount = Number(snapshot.data()?.newCount || 0);
        updateBadge();
      }
    );

    const unsubscribeAvisos = onSnapshot(
      query(collection(firestore, 'avisos')),
      (snapshot) => {
        avisoCount = snapshot.docs.filter((docSnap) => {
          const visualizadosPor = docSnap.data().visualizadosPor;

          return (
            !Array.isArray(visualizadosPor) ||
            !visualizadosPor.includes(usuario.uid)
          );
        }).length;

        updateBadge();
      }
    );

    return () => {
      unsubscribeEscalas();
      unsubscribeRepertorios();
      unsubscribeAvisos();
    };
  }, [usuario]);
}

function obterVersaoMeta(data: any): number {
  const lastUpdated = data?.lastUpdated || data?.updatedAt || data?.criadoEm;

  if (typeof lastUpdated?.toMillis === 'function') {
    return lastUpdated.toMillis();
  }

  if (lastUpdated instanceof Date) {
    return lastUpdated.getTime();
  }

  if (typeof lastUpdated === 'number') {
    return lastUpdated;
  }

  const parsed = Date.parse(String(lastUpdated || ''));

  if (!Number.isNaN(parsed)) {
    return parsed;
  }

  return Number(data?.newCount || 0);
}

function useMetaUpdateNotifications(usuario: User | null) {
  const versoesIniciais = useRef<Record<string, number | null>>({
    escalas: null,
    repertorios: null,
  });

  useEffect(() => {
    if (!usuario) {
      versoesIniciais.current = {
        escalas: null,
        repertorios: null,
      };

      return;
    }

    const observarMeta = (
      tipo: 'escalas' | 'repertorios',
      titulo: string,
      corpo: (count: number) => string
    ) =>
      onSnapshot(doc(firestore, 'meta', tipo), async (snapshot) => {
        const data = snapshot.data();
        const count = Number(data?.newCount || 0);
        const versaoAtual = obterVersaoMeta(data);
        const versaoAnterior = versoesIniciais.current[tipo];

        if (versaoAnterior === null) {
          versoesIniciais.current[tipo] = versaoAtual;
          return;
        }

        versoesIniciais.current[tipo] = versaoAtual;

        if (count <= 0 || versaoAtual <= versaoAnterior) {
          return;
        }

        try {
          await Notifications.setBadgeCountAsync(count);

          await Notifications.scheduleNotificationAsync({
            content: {
              title: titulo,
              body: corpo(count),
              badge: count,
              data: {
                url: tipo === 'escalas' ? '/escalas' : '/repertorios',
              },
            },
            trigger: null,
          });
        } catch (error) {
          console.log(`Erro ao notificar ${tipo}:`, error);
        }
      });

    const unsubscribeEscalas = observarMeta(
      'escalas',
      'Escala atualizada',
      (count) =>
        count > 1
          ? `${count} atualizações de escala`
          : 'Uma escala foi criada ou atualizada'
    );

    const unsubscribeRepertorios = observarMeta(
      'repertorios',
      'Repertório atualizado',
      (count) =>
        count > 1
          ? `${count} atualizações de repertório`
          : 'Um repertório foi criado ou atualizado'
    );

    return () => {
      unsubscribeEscalas();
      unsubscribeRepertorios();
    };
  }, [usuario]);
}

function NotificationRequiredScreen({
  permission,
  registering,
  onRequestPermission,
  onContinueWithoutNotifications,
}: {
  permission: NotificationPermission | 'unsupported' | 'checking';
  registering: boolean;
  onRequestPermission: () => void;
  onContinueWithoutNotifications: () => void;
}) {
  const isDenied = permission === 'denied';
  const isUnsupported = permission === 'unsupported';

  return (
    <SafeAreaView style={styles.notificationGate}>
      <View style={styles.notificationPanel}>
        <View style={styles.notificationIcon}>
          <Text style={styles.notificationIconText}>!</Text>
        </View>

        <Text style={styles.notificationTitle}>Ative as notificações</Text>

        <Text style={styles.notificationText}>
          Ative para receber novas escalas, repertórios e avisos importantes do ministério.
        </Text>

        {isUnsupported ? (
          <Text style={styles.notificationWarning}>
            Este navegador não suporta notificações PWA. Abra no Chrome, Edge ou instale o PWA pela tela inicial do celular.
          </Text>
        ) : isDenied ? (
          <Text style={styles.notificationWarning}>
            A permissão foi bloqueada. Libere as notificações nas configurações do navegador para continuar.
          </Text>
        ) : null}

        <Pressable
          style={[
            styles.notificationButton,
            (registering || isUnsupported) && styles.notificationButtonDisabled,
          ]}
          onPress={onRequestPermission}
          disabled={registering || isUnsupported}
        >
          <Text style={styles.notificationButtonText}>
            {registering
              ? 'Ativando...'
              : isDenied
                ? 'Tentar novamente'
                : 'Ativar notificações'}
          </Text>
        </Pressable>

        <Pressable
          style={styles.notificationContinueButton}
          onPress={onContinueWithoutNotifications}
        >
          <Text style={styles.notificationContinueButtonText}>
            Continuar sem notificações
          </Text>
        </Pressable>
      </View>
    </SafeAreaView>
  );
}

const linking = {
  prefixes: [Platform.OS === 'web' ? window.location.origin + '/' : ''],
  config: {
    screens: {
      Inicio: 'inicio',
      CriarEscala: 'criar-escala',
      Escalas: 'escalas',
      DetalhesEscala: 'detalhes-escala',
      Repertorios: 'repertorios',
      AdicionarRepertorio: 'adicionar-repertorio',
      DetalheRepertorio: 'detalhe-repertorio',
      VisualizarArquivo: 'visualizar-arquivo',
      Presenca: 'presenca',
      Avisos: 'avisos',
      Ensaios: 'ensaios',
      Aniversariantes: 'aniversariantes',
      Interacao: 'interacao',
      Agenda: 'agenda',
    },
  },
};

const notificationRouteByPath: Record<string, string> = {
  inicio: 'Inicio',
  escalas: 'Escalas',
  repertorios: 'Repertorios',
  avisos: 'Avisos',
  ensaios: 'Ensaios',
  aniversariantes: 'Aniversariantes',
  interacao: 'Interacao',
  agenda: 'Agenda',
};

function getNotificationRoute(url: string) {
  try {
    const parsed = new URL(
      url,
      typeof window !== 'undefined'
        ? window.location.origin
        : 'https://worldinovabr.github.io'
    );

    const parts = parsed.pathname.split('/').filter(Boolean);
    const lastPart = parts[parts.length - 1] || '';

    return notificationRouteByPath[lastPart] || null;
  } catch {
    const normalized =
      url
        .split('?')[0]
        .split('#')[0]
        .split('/')
        .filter(Boolean)
        .pop() || '';

    return notificationRouteByPath[normalized] || null;
  }
}

function navigateFromNotificationUrl(url: string) {
  const route = getNotificationRoute(url);

  if (!route) return;

  if (navigationRef.isReady()) {
    const currentRoute = navigationRef.getCurrentRoute()?.name;

    if (currentRoute === 'SplashLogo') {
      setTimeout(() => navigateFromNotificationUrl(url), 500);
      return;
    }

    navigationRef.navigate(route);
    return;
  }

  setTimeout(() => navigateFromNotificationUrl(url), 400);
}

export default function App(): JSX.Element {
  const [usuario, setUsuario] = useState<User | null>(null);
  const [carregando, setCarregando] = useState(true);
  const notificationGate = useWebNotificationGate(usuario);
  const pendingNotificationUrl = useRef<string | null>(null);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (usuarioAtual) => {
      setUsuario(
        usuarioAtual && usuarioAtual.emailVerified ? usuarioAtual : null
      );

      setCarregando(false);
    });

    return unsubscribe;
  }, []);

  useRegisterForPushNotifications(usuario);
  useInstalledAppBadge(usuario);
  useMetaUpdateNotifications(usuario);

  useEffect(() => {
    if (
      Platform.OS !== 'web' ||
      typeof navigator === 'undefined' ||
      !usuario
    ) {
      return;
    }

    const handleServiceWorkerMessage = (event: MessageEvent) => {
      if (
        event.data?.type !== 'WORSHIP_NOTIFICATION_CLICK' ||
        !event.data?.url
      ) {
        return;
      }

      pendingNotificationUrl.current = event.data.url;
      navigateFromNotificationUrl(event.data.url);
    };

    navigator.serviceWorker?.addEventListener(
      'message',
      handleServiceWorkerMessage
    );

    return () =>
      navigator.serviceWorker?.removeEventListener(
        'message',
        handleServiceWorkerMessage
      );
  }, [usuario]);

  useEffect(() => {
    if (!usuario) return;

    const subscription =
      Notifications.addNotificationResponseReceivedListener((response) => {
        const url = response.notification.request.content.data?.url;

        if (typeof url !== 'string') return;

        pendingNotificationUrl.current = url;
        navigateFromNotificationUrl(url);
      });

    return () => subscription.remove();
  }, [usuario]);

  // Trata o clique na notificação quando o app estava fechado (cold start)
  useEffect(() => {
    if (Platform.OS === 'web' || !usuario) return;

    Notifications.getLastNotificationResponseAsync().then((response) => {
      const url = response?.notification.request.content.data?.url;

      if (typeof url !== 'string') return;

      pendingNotificationUrl.current = url;
      navigateFromNotificationUrl(url);
    });
  }, [usuario]);

  useEffect(() => {
    if (
      Platform.OS !== 'web' ||
      typeof window === 'undefined' ||
      !usuario
    ) {
      return;
    }

    const currentUrl = window.location.href;
    const route = getNotificationRoute(currentUrl);

    if (!route) return;

    pendingNotificationUrl.current = currentUrl;
    navigateFromNotificationUrl(currentUrl);
  }, [usuario]);

  if (carregando) {
    return (
      <SafeAreaView style={styles.loadingContainer}>
        <ActivityIndicator size="large" color="#FF9A3C" />
      </SafeAreaView>
    );
  }

  if (notificationGate.shouldBlock) {
    return (
      <SafeAreaView style={styles.container}>
        <NotificationRequiredScreen
          permission={notificationGate.permission}
          registering={notificationGate.registering}
          onRequestPermission={notificationGate.requestPermission}
          onContinueWithoutNotifications={
            notificationGate.continueWithoutNotifications
          }
        />

        <InstallPWAButton />
        <Toast />
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={styles.container}>
      <NavigationContainer
        ref={navigationRef}
        linking={linking}
        onReady={() => {
          if (pendingNotificationUrl.current) {
            navigateFromNotificationUrl(pendingNotificationUrl.current);
          }
        }}
        onStateChange={() => {
          if (!pendingNotificationUrl.current) return;

          const currentRoute = navigationRef.getCurrentRoute()?.name;

          if (currentRoute === 'SplashLogo') return;

          const route = getNotificationRoute(
            pendingNotificationUrl.current
          );

          if (route && currentRoute !== route) {
            navigateFromNotificationUrl(pendingNotificationUrl.current);
            return;
          }

          pendingNotificationUrl.current = null;
        }}
      >
        {usuario ? <AppNavigator /> : <AuthNavigator />}
        <InstallPWAButton />
        <Toast />
      </NavigationContainer>
    </SafeAreaView>
  );
}

