import { useEffect, useState } from 'react';
import { doc, onSnapshot } from 'firebase/firestore';
import { firestore } from '../services/firebaseConfig';

export type ChavePermissao =
  | 'gerenciarEscalas'
  | 'gerenciarAvisos'
  | 'gerenciarRepertorios'
  | 'gerenciarEnsaios'
  | 'gerenciarAniversariantes';

// Segunda via de permissao (painel Admin): le o campo "permissoes" do perfil do usuario.
export function usePermissaoUsuario(uid: string | null | undefined, chave: ChavePermissao): boolean {
  const [permitido, setPermitido] = useState(false);

  useEffect(() => {
    if (!uid) {
      setPermitido(false);
      return;
    }

    const unsubscribe = onSnapshot(
      doc(firestore, 'usuarios', uid),
      snapshot => setPermitido(snapshot.data()?.permissoes?.[chave] === true),
      () => setPermitido(false)
    );

    return unsubscribe;
  }, [uid, chave]);

  return permitido;
}
